class Graph:
    def __init__(self):
        self._nodes = set()
        self._edges = {}

    def add_node(self, n):
        self._nodes.add(n)

    def add_edge(self, a, b, weight=1):
        if weight <= 0:
            raise ValueError("Weight must be a positive number")
        self.add_node(a)
        self.add_node(b)
        if a not in self._edges:
            self._edges[a] = {}
        self._edges[a][b] = weight

    def nodes(self):
        return sorted(self._nodes)

    def neighbors(self, a):
        if a not in self._edges:
