class Graph:
    def bfs(self, start):
        if start not in self._nodes:
            raise KeyError(f"Start node {start} not in graph")
        
        visited = set()
        queue = [start]
        result = []
        
        while queue:
            node = queue.pop(0)
            if node not in visited:
                visited.add(node)
                result.append(node)
                queue.extend(sorted(self.neighbors(node) - visited))
        
        return result
    def __init__(self):
        self._nodes = set()
        self._edges = {}

    def add_node(self, n):
        self._nodes.add(n)

    def add_edge(self, a, b, weight=1):
        if weight <= 0:
            raise ValueError("Weight must be a positive number")
        self.add_node(a)
        self.add_node(b)
        if a not in self._edges:
